// Raises one alert through the plugin surface. Two of these prove that each
// plugin's own copy of `app` carries the surface — the cross-plugin failure
// the core subsystem exists to avoid.
module.exports = function (app) {
  return {
    id: 'alertsplugin-a',
    name: 'Alerts plugin a',
    schema: function () {
      return { type: 'object', properties: {} }
    },
    start: function () {
      app.alerts
        .raise({
          path: 'test.plugina.condition',
          priority: 'warning',
          message: 'Raised by plugin a'
        })
        .catch(function (err) {
          app.error('alerts raise failed: ' + err.message)
        })
    },
    stop: function () {},
    registerWithRouter: function (router) {
      // Reads the active set back through the plugin surface, so a test can
      // compare what a plugin sees with what REST and the deltas carry.
      router.get('/seen', function (req, res) {
        res.json(
          app.alerts.list().map(function (alert) {
            return alert.path
          })
        )
      })
    }
  }
}
